b(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_evento_saude_config d WHERE id_evento IN ('43533','44805','46084','47031')),'tb_percurso_migracoes_strava',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_percurso_migracoes_strava d WHERE id_evento IN ('43533','44805','46084','47031')),'tb_leaderboard_percurso',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_leaderboard_percurso d WHERE id_evento IN ('43533','44805','46084','47031')),'tb_resultados_resumo',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_resultados_resumo d WHERE id_evento IN ('43533','44805','46084','47031')),'tb_inscricoes',(SELECT jsonb_build_object('count',count(*),'hash',md5(string_agg(md5(to_jsonb(d)::text),'' ORDER BY md5(to_jsonb(d)::text)))) FROM tb_inscricoes d WHERE id_evento IN ('43533','44805','46084','47031'))) INTO deps;
